// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= address(this).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        bool isOwner = (actor == address(this));
        assertTrue(ok == isOwner);
    }
}
